code.C:
#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        int rem = n % 3;
        if (rem == 0) {
            printf("The number is divisible by 3\n");
        } else {
            printf("The number is not divisible by 3 and gives a remainder %d\n", rem);
        }
    }
    return 0;
}

code.C++:
