        else cout << "The number is not divisible by 3 and gives a remainder " << rem << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int rem = n % 3;
            if (rem == 0) System.out.println("The number is divisible by 3");
            else System.out.println("The number is not divisible by 3 and gives a remainder " + rem);
        }
    }
}

code.Python3:
import sys

def main():
    s = sys.stdin.read().strip()
    if s:
        n = int(s)
        rem = n % 3
        if rem == 0:
            print("The number is divisible by 3")
        else:
            print(f"The number is not divisible by 3 and gives a remainder {rem}")

if __name__ == '__main__':
    main()

